(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-287":{scenario:{company:"Saola Cloud Solutions",supervisor:{name:"Vi Minh Khoa",role:{vi:"Trưởng nhóm Phát triển Kinh doanh",en:"Business Development Team Lead"}},ref_code:"LD-5821",title:{vi:"Đúng giai đoạn. Đúng điểm. Đúng sự thật.",en:"Right stage. Right score. Right facts."},brief:{vi:"Bạn rà soát lead LD-5821 trước khi bàn giao cho AE: công ty logistics 320 nhân sự (đúng ICP), người liên hệ là Trưởng phòng CNTT (chưa phải người quyết định), đã dự webinar, xem trang bảng giá 2 lần, mở email 6 lần nhưng chưa trả lời, chưa xác nhận ngân sách, dự kiến triển khai sau 9 tháng. Quy chuẩn: SQL cần ít nhất 3/4 tiêu chí BANT và bắt buộc có Authority. Sửa giai đoạn lead và điểm lead (mô hình chấm điểm mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are reviewing lead LD-5821 before handing it to an AE: a 320-employee logistics company (ICP fit), the contact is the IT Manager (not the decision maker), attended a webinar, viewed the pricing page twice, opened emails 6 times without replying, budget unconfirmed, go-live expected in 9 months. Standard: an SQL needs at least 3 of 4 BANT criteria including Authority. Correct the lead stage and lead score (training scoring model), then write an evidence-based report."},reference_title:{vi:"Phiếu sàng lọc BANT & mô hình điểm lead đã duyệt · LD-5821",en:"Approved BANT sheet & lead scoring model · LD-5821"},fields:[{id:"LEAD_STAGE",label:{vi:"Giai đoạn lead",en:"Lead stage"},initial:"SQL",expected:"MQL",choices:["SQL","MQL","DQ"],reference:"Phiếu sàng lọc BANT",hint:{vi:"Đếm số tiêu chí BANT có bằng chứng; người liên hệ chưa có thẩm quyền quyết định.",en:"Count the BANT criteria with evidence; the contact has no decision authority."}},{id:"LEAD_SCORE",label:{vi:"Điểm lead",en:"Lead score"},initial:"98",expected:"70",reference:"Mô hình điểm lead",ref_value:{vi:"Fit: ICP, 320 nhân sự, cấp quản lý; hành vi: 1 webinar, 2 lần xem bảng giá, 6 lần mở email; triển khai sau 9 tháng",en:"Fit: ICP, 320 staff, manager level; activity: 1 webinar, 2 pricing views, 6 email opens; go-live in 9 months"},hint:{vi:"Lượt mở email không được tính điểm, và thời điểm triển khai xa phải bị trừ điểm.",en:"Email opens earn no points, and a distant go-live date must be deducted."}}],sop32:{vi:"Điểm lead = ngành ICP +20, quy mô 200-1000 nhân sự +15, cấp quản lý +10, dự webinar +15, mỗi lần xem bảng giá +10; lượt mở email không tính điểm; triển khai sau hơn 6 tháng -10. SQL từ 80 điểm (mô phỏng).",en:"Lead score = ICP industry +20, size 200-1000 staff +15, manager level +10, webinar attended +15, each pricing page view +10; email opens score zero; go-live beyond 6 months -10. SQL from 80 points (training model)."},context:{label:"CRM / LD-5821",metrics:[{label:{vi:"Quy mô doanh nghiệp",en:"Company size"},value:"320 FTE"},{label:{vi:"Lượt xem bảng giá",en:"Pricing page views"},value:"2"},{label:{vi:"Lượt mở email",en:"Email opens"},value:"6"},{label:{vi:"Ngưỡng SQL mô phỏng",en:"Training SQL threshold"},value:"80"}]},crisis:{vi:"Quản lý kinh doanh khu vực nhắn: “Cuối tháng còn thiếu 3 SQL. Cứ chuyển LD-5821 sang SQL, ghi là khách đã xác nhận ngân sách, AE gọi lại sau là được.”",en:"The regional sales manager messages you: “We are 3 SQLs short this month. Just move LD-5821 to SQL and note that the budget is confirmed, the AE can call later.”"},options:{safe:{vi:"Giữ MQL và điểm đúng mô hình, ghi trung thực BANT, báo trưởng nhóm; đề xuất cuộc gọi khám phá với giám đốc vận hành để xác nhận ngân sách và thẩm quyền.",en:"Keep MQL and the correct model score, record BANT honestly, inform the team lead; propose a discovery call with the operations director to confirm budget and authority."},shortcut:{vi:"Chuyển sang SQL và ghi đã có ngân sách cho đủ chỉ tiêu, AE sẽ tự lọc lại sau.",en:"Move it to SQL and record a confirmed budget to hit the target, the AE will filter it later."},wait:{vi:"Để nguyên bản nháp, không bàn giao và không báo ai cho đến hết tháng.",en:"Leave the draft as it is, hand nothing over and tell no one until month end."}},questions:{vi:["Vì sao LD-5821 là MQL chứ không phải SQL? Tiêu chí BANT nào còn thiếu và bằng chứng nằm ở đâu?","Trình bày cách tính điểm lead theo mô hình và rủi ro khi ghi khống ngân sách để đủ chỉ tiêu SQL."],en:["Why is LD-5821 an MQL rather than an SQL? Which BANT criteria are missing and where is the evidence?","Explain how you calculated the lead score and the risk of recording a fake budget to meet the SQL target."]},hints:{vi:["Đặt bản nháp cạnh phiếu sàng lọc BANT và đánh dấu tiêu chí nào có bằng chứng, tiêu chí nào chưa.","Cộng từng hạng mục fit và hành vi theo SOP mục 3.2, chú ý hạng mục không tính điểm và hạng mục bị trừ.","Đọc lại SOP mục 4.2: dữ liệu CRM phải trung thực, mọi áp lực sửa giai đoạn phải được báo cáo."],en:["Place the draft next to the BANT sheet and mark which criteria have evidence and which do not.","Add each fit and activity item per SOP 3.2, watching for items that score zero and items that deduct.","Re-read SOP 4.2: CRM data must be truthful and any pressure to change a stage must be escalated."]}},learning:{summary:{vi:"Chuyên viên phát triển kinh doanh (BDR) mở đầu chu trình bán hàng B2B: nghiên cứu thị trường mục tiêu, tìm và tiếp cận khách hàng tiềm năng qua điện thoại, email, mạng xã hội nghề nghiệp và sự kiện, sàng lọc theo hồ sơ khách hàng lý tưởng (ICP) và khung BANT, rồi đặt lịch hẹn chất lượng cho chuyên viên kinh doanh (AE). Giá trị cốt lõi là đường ống cơ hội thật, dữ liệu CRM trung thực và hoạt động tiếp cận tuân thủ quy định về dữ liệu cá nhân, chống cuộc gọi và thư rác.",en:"A Business Development Representative opens the B2B sales cycle: researching target markets, finding and engaging prospects by phone, email, professional networks and events, qualifying them against the ideal customer profile (ICP) and BANT, then booking quality meetings for account executives (AEs). The core value is a real pipeline, honest CRM data and outreach that complies with personal data and anti-spam rules."},responsibilities:{vi:["Nghiên cứu ngành, xây danh sách tài khoản mục tiêu theo ICP và vẽ sơ đồ người ảnh hưởng.","Thực hiện chuỗi tiếp cận đa kênh: gọi điện, email cá nhân hóa, mạng xã hội nghề nghiệp.","Sàng lọc nhu cầu theo BANT hoặc MEDDIC và ghi nhận bằng chứng vào CRM.","Đặt lịch hẹn khám phá và bàn giao SQL cho AE kèm ghi chú đầy đủ.","Nuôi dưỡng MQL chưa sẵn sàng, cập nhật điểm lead và báo cáo hiệu quả kênh hằng tuần."],en:["Research industries, build target account lists by ICP and map the influencers.","Run multichannel cadences: calls, personalized emails and professional networks.","Qualify needs with BANT or MEDDIC and record the evidence in the CRM.","Book discovery meetings and hand SQLs to AEs with complete notes.","Nurture MQLs that are not ready, update lead scores and report channel results weekly."]},competencies:[{name:{vi:"Nghiên cứu khách hàng",en:"Account research"},desc:{vi:"Đọc báo cáo ngành, tin tuyển dụng, website để tìm tín hiệu nhu cầu và người quyết định.",en:"Read industry reports, job posts and websites to find buying signals and decision makers."}},{name:{vi:"Tiếp cận & mở lời",en:"Prospecting & opening"},desc:{vi:"Viết email ngắn có giá trị, mở cuộc gọi trong 30 giây đầu và xử lý từ chối ban đầu.",en:"Write short value-led emails, open a call in the first 30 seconds and handle early objections."}},{name:{vi:"Sàng lọc có kỷ luật",en:"Disciplined qualification"},desc:{vi:"Áp dụng ICP, BANT và mô hình điểm lead nhất quán, không thổi phồng giai đoạn.",en:"Apply ICP, BANT and the lead scoring model consistently without inflating stages."}},{name:{vi:"Quản trị dữ liệu CRM",en:"CRM data hygiene"},desc:{vi:"Ghi hoạt động, giai đoạn và nguồn lead chính xác để đo được phễu chuyển đổi.",en:"Log activities, stages and lead sources accurately so the funnel can be measured."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Chỉ dùng dữ liệu có nguồn hợp pháp, tôn trọng yêu cầu từ chối liên hệ và báo cáo trung thực.",en:"Use only lawfully sourced data, honor opt-out requests and report truthfully."}}],knowledge:{vi:["Khung sàng lọc BANT (Ngân sách, Thẩm quyền, Nhu cầu, Thời điểm) và MEDDIC cho thương vụ phức tạp.","Phễu lead MQL, SAL, SQL và thỏa thuận định nghĩa chung giữa marketing và kinh doanh (SLA).","Hồ sơ khách hàng lý tưởng (ICP), chân dung người mua và sơ đồ đơn vị ra quyết định.","Nghị định 91/2020/NĐ-CP về chống tin nhắn rác, thư điện tử rác, cuộc gọi rác.","Luật Bảo vệ dữ liệu cá nhân và văn bản hướng dẫn hiện hành: căn cứ xử lý dữ liệu, quyền phản đối của chủ thể."],en:["BANT qualification (Budget, Authority, Need, Timing) and MEDDIC for complex deals.","The MQL, SAL, SQL funnel and the shared marketing-sales definition agreement (SLA).","Ideal customer profile (ICP), buyer personas and buying committee mapping.","Decree 91/2020/ND-CP on fighting spam messages, spam emails and spam calls.","Vietnam's Personal Data Protection Law and current guidance: lawful bases and the data subject's right to object."]},tools:["Hệ thống CRM","Nền tảng sales engagement","Tổng đài VoIP / softphone","Cơ sở dữ liệu doanh nghiệp B2B","Công cụ đặt lịch hẹn trực tuyến"],kpis:{vi:["Số cuộc hẹn đủ chuẩn (SQL) được AE chấp nhận mỗi tháng.","Tỷ lệ chuyển đổi từ cuộc hẹn sang cơ hội bán hàng.","Tỷ lệ kết nối cuộc gọi và tỷ lệ phản hồi email của chuỗi tiếp cận.","Giá trị đường ống cơ hội tạo ra trên mỗi BDR mỗi quý."],en:["Qualified meetings (SQLs) accepted by AEs per month.","Conversion rate from meeting to sales opportunity.","Call connect rate and email reply rate of each cadence.","Pipeline value generated per BDR per quarter."]},day:[{time:"08:30",vi:"Nghiên cứu 15 tài khoản mục tiêu mới, tìm tín hiệu nhu cầu và người quyết định.",en:"Research 15 new target accounts for buying signals and decision makers."},{time:"09:30",vi:"Khung giờ gọi tập trung: gọi lạnh và gọi theo dõi các lead đã tương tác.",en:"Power hour: cold calls and follow-up calls to engaged leads."},{time:"13:30",vi:"Gửi chuỗi email cá nhân hóa, trả lời phản hồi và đặt lịch hẹn.",en:"Send personalized email steps, answer replies and book meetings."},{time:"15:30",vi:"Họp bàn giao SQL với AE, cập nhật giai đoạn và ghi chú BANT trên CRM.",en:"Hand SQLs over to AEs, update stages and BANT notes in the CRM."},{time:"17:00",vi:"Rà soát chỉ số trong ngày và chuẩn bị danh sách gọi cho hôm sau.",en:"Review the day's metrics and prepare tomorrow's call list."}],mistakes:{vi:["Đẩy lead lên SQL khi chưa xác nhận thẩm quyền và ngân sách, làm AE mất thời gian.","Tính lượt mở email vào điểm lead dù dữ liệu mở thư không đáng tin cậy.","Dùng danh sách liên hệ không rõ nguồn hoặc tiếp tục gọi người đã yêu cầu từ chối."],en:["Pushing a lead to SQL before authority and budget are confirmed, wasting AE time.","Scoring email opens even though open tracking is unreliable.","Using contact lists of unknown origin or calling people who have opted out."]},career:[{vi:"Thực tập sinh phát triển kinh doanh",en:"Business development intern"},{vi:"Chuyên viên phát triển kinh doanh (BDR)",en:"Business Development Representative"},{vi:"Chuyên viên kinh doanh khách hàng (AE)",en:"Account Executive"},{vi:"Quản lý phát triển kinh doanh",en:"Business Development Manager"}],glossary:[{term:"ICP",vi:"Hồ sơ khách hàng lý tưởng: ngành, quy mô, khu vực của nhóm khách hàng phù hợp nhất với sản phẩm.",en:"Ideal customer profile: the industry, size and region of the best-fit customer group."},{term:"BANT",vi:"Khung sàng lọc gồm Ngân sách, Thẩm quyền, Nhu cầu và Thời điểm mua.",en:"Qualification framework covering Budget, Authority, Need and Timing."},{term:"MQL",vi:"Lead đạt tiêu chí marketing (phù hợp, có tương tác) nhưng chưa đủ điều kiện bàn giao bán hàng.",en:"A lead that meets marketing criteria (fit and engagement) but is not yet ready for sales."},{term:"SQL",vi:"Lead đã được sàng lọc đủ tiêu chí để AE mở cơ hội bán hàng.",en:"A lead qualified enough for an AE to open a sales opportunity."},{term:"Cadence",vi:"Chuỗi tiếp cận gồm nhiều điểm chạm đa kênh theo lịch định sẵn.",en:"A planned sequence of multichannel outreach touches."}],quiz:[{q:{vi:"Theo mô hình trong bài, lead có ICP, quy mô 450 nhân sự, cấp quản lý, dự webinar, xem bảng giá 1 lần, mở email 4 lần, triển khai sau 8 tháng. Điểm lead là bao nhiêu?",en:"Under the training model, a lead is ICP, 450 staff, manager level, attended a webinar, viewed pricing once, opened emails 4 times, go-live in 8 months. What is the score?"},options:{vi:["60","72","70","50"],en:["60","72","70","50"]},answer:0,explain:{vi:"20 + 15 + 10 + 15 + 10 - 10 = 60; lượt mở email không tính điểm.",en:"20 + 15 + 10 + 15 + 10 - 10 = 60; email opens score zero."}},{q:{vi:"Theo quy chuẩn trong bài, lead đạt SQL cần điều kiện nào?",en:"Under the training standard, what does an SQL require?"},options:{vi:["Mở email ít nhất 3 lần","Đã dự một webinar","Đạt ít nhất 3/4 tiêu chí BANT, bắt buộc có Authority","Người liên hệ thuộc phòng CNTT"],en:["At least 3 email opens","Attended one webinar","At least 3 of 4 BANT criteria, Authority mandatory","The contact works in IT"]},answer:2,explain:{vi:"SQL cần bằng chứng sàng lọc; thiếu người có thẩm quyền thì chưa thể mở cơ hội.",en:"An SQL needs qualification evidence; without authority no opportunity can be opened."}},{q:{vi:"Khách hàng tiềm năng nói “đừng gọi cho tôi nữa”. Bạn làm gì?",en:"A prospect says “do not call me again”. What do you do?"},options:{vi:["Đổi số khác gọi lại sau một tuần","Chuyển sang gửi email quảng cáo","Nhờ đồng nghiệp gọi thay","Ghi nhận từ chối trên CRM, dừng mọi kênh và cảm ơn khách"],en:["Call again from another number next week","Switch to promotional emails","Ask a colleague to call instead","Record the opt-out in the CRM, stop all channels and thank them"]},answer:3,explain:{vi:"Tôn trọng quyền từ chối là yêu cầu pháp lý và đạo đức; tiếp tục liên hệ có thể bị coi là cuộc gọi, thư rác.",en:"Honoring opt-outs is a legal and ethical duty; continued contact can count as spam calls or emails."}},{q:{vi:"Vì sao MQL nên được nuôi dưỡng thay vì bàn giao ngay cho AE?",en:"Why should an MQL be nurtured instead of handed straight to an AE?"},options:{vi:["Vì MQL không có giá trị kinh doanh","Vì chưa đủ tín hiệu sẵn sàng mua; bàn giao sớm làm giảm tỷ lệ chuyển đổi","Vì AE chỉ nhận lead từ sự kiện","Vì hệ thống CRM không cho phép"],en:["Because MQLs have no business value","Because buying readiness is not proven; early handover lowers conversion","Because AEs only accept event leads","Because the CRM does not allow it"]},answer:1,explain:{vi:"Nuôi dưỡng giúp lead chín muồi, giữ niềm tin giữa BDR và AE và làm phễu dự báo chính xác hơn.",en:"Nurturing matures the lead, keeps BDR-AE trust and makes the funnel forecast more accurate."}}],tools_en:["CRM system","Sales engagement platform","VoIP phone system / softphone","B2B company database","Online appointment scheduling tools"]}}})})(window.KKR);
